352: // Remediate executes corrective actions for CoreDNS failures.
353: func (m *CoreDNSModule) Remediate(ctx context.Context, evalResult *module.EvalResult) (*module.RemediateResult, error) {
354: 	log := logf.FromContext(ctx).WithName(corednsName)
355: 	reason := evalResult.Reason
356: 
357: 	// Enforce 30s remediation cooldown window to prevent restart-thrashing
358: 	cooldownWindow := 30 * time.Second
359: 	if !m.lastRemediatedAt.IsZero() && time.Since(m.lastRemediatedAt) < cooldownWindow {
360: 		rem := cooldownWindow - time.Since(m.lastRemediatedAt).Round(time.Second)
361: 		msg := fmt.Sprintf("Remediation cooldown active (%v remaining); skipping action to prevent restart thrashing", rem)
362: 		log.Info(msg)
363: 		return &module.RemediateResult{Action: msg, Success: true}, nil
364: 	}
