379: 			return &module.RemediateResult{Action: "scale coredns deployment", Success: false, Err: err}, err
380: 		}
381: 
382: 		m.lastRemediatedAt = time.Now()
383: 		msg := fmt.Sprintf("Scaled CoreDNS deployment back up to %d replicas", targetReplicas)
384: 		log.Info(msg)
385: 		return &module.RemediateResult{Action: msg, Success: true}, nil
386: 	}
