390: 		var cm corev1.ConfigMap
391: 		cmKey := types.NamespacedName{Namespace: corednsNamespace, Name: corednsName}
392: 		if err := m.Client.Get(ctx, cmKey, &cm); err != nil {
393: 			return &module.RemediateResult{Action: "fetch coredns configmap", Success: false, Err: err}, err
394: 		}
