405: 		// Wait briefly / verify ConfigMap commit before triggering rolling restart
406: 		for range 5 {
407: 			var checkCM corev1.ConfigMap
408: 			if err := m.Client.Get(ctx, cmKey, &checkCM); err == nil {
409: 				if strings.Contains(checkCM.Data[corefileName], "forward . /etc/resolv.conf") {
410: 					break
411: 				}
412: 			}
413: 			time.Sleep(100 * time.Millisecond)
