import json
import re

transcript_path = r"C:\Users\ratho\.gemini\antigravity-ide\brain\5bff4a54-156a-4054-b91d-8182b8d1b644\.system_generated\logs\transcript_full.jsonl"

with open(transcript_path, "r", encoding="utf-8") as f:
    lines = [json.loads(l) for l in f if l.strip()]

turns = []
current_turn = None

for step in lines:
    stype = step.get("type")
    source = step.get("source")

    if stype == "USER_INPUT":
        current_turn = {
            "step_index": step.get("step_index"),
            "raw_user_content": step.get("content", ""),
            "items": []
        }
        turns.append(current_turn)
    elif current_turn is not None:
        if stype == "PLANNER_RESPONSE":
            content = step.get("content")
            tool_calls = step.get("tool_calls", [])
            if tool_calls:
                for tc in tool_calls:
                    current_turn["items"].append({"type": "tool_call", "name": tc.get("name"), "args": tc.get("args")})
            if content:
                current_turn["items"].append({"type": "response", "content": content})

print(f"Total conversation turns: {len(turns)}")
for i, t in enumerate(turns):
    print(f"\n================ Turn {i+1} (Step {t['step_index']}) ================")
    user_c = t['raw_user_content']
    req_m = re.search(r"<USER_REQUEST>(.*?)</USER_REQUEST>", user_c, re.DOTALL)
    user_text = req_m.group(1).strip() if req_m else user_c.strip()
    print("USER PROMPT:\n", user_text[:150] + ("..." if len(user_text) > 150 else ""))
    print(f"ITEMS in turn: {len(t['items'])}")
    for it in t['items']:
        if it['type'] == 'tool_call':
            print(f"  Tool: {it['name']}")
        else:
            print(f"  Response ({len(it['content'])} chars): {it['content'][:80].replace(chr(10), ' ')}...")
